import { Fragment } from 'react/jsx-runtime';
import SampleImg from '~/shared/assets/img/company_sample.png';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const CaptureBusinessLicensePage = () => {
  const { navigate } = useNavigate();

  const handleCaptureBusinessLicense = () => {
    window.webViewBridge.send(NativeFunction.BusinessLicenseScan, {
      success: () => {
        navigate(PATHS.issueWallet.confirm.businessLicense);
      },
    });
  };
  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <div className="sub-step">
          <span>1step</span>
          <span className="on">2step</span>
          <span>2step</span>
        </div>
        <div className="sub-desc">
          <p>{i18n.t('prepareBusinessLicense')}</p>
        </div>
        <div className="sample-area">
          <div className="id-sample-area">
            <div className="id-sample-box bay-one">
              <div className="id-sample-img">
                <img src={SampleImg} className="company" alt={i18n.t('businessLicenseExample')} />
              </div>
              <p>{i18n.t('businessLicenseExample')}</p>
            </div>
          </div>
        </div>
      </div>
      <div className="btm-btn-area">
        <button type="button" className="btm-btn app" onClick={handleCaptureBusinessLicense}>
          {i18n.t('captureBusinessLicense')}
        </button>
      </div>
    </Fragment>
  );
};
